// A small model of two rules from the Claude Code docs, so you can watch them without admin rights:
// 1. drop-ins in managed-settings.d merge in name order (single values: later wins; lists: combine; objects: merge key by key)
// 2. the merged policy sits above the laptop's own settings, and nothing below it overrides a managed key
import { readdirSync, readFileSync } from "node:fs";

const read = (path) => JSON.parse(readFileSync(path, "utf8"));
const isObject = (v) => v && typeof v === "object" && !Array.isArray(v);
const unique = (list) => [...new Map(list.map((item) => [JSON.stringify(item), item])).values()];

const merge = (a, b) => {
  const out = { ...a };
  for (const [key, value] of Object.entries(b)) {
    if (Array.isArray(out[key]) && Array.isArray(value)) out[key] = unique([...out[key], ...value]);
    else if (key === "extraKnownMarketplaces") out[key] = { ...out[key], ...value }; // same name: the later entry replaces it whole
    else if (isObject(out[key]) && isObject(value)) out[key] = merge(out[key], value);
    else out[key] = value;
  }
  return out;
};

const dir = "policy/managed-settings.d";
const files = readdirSync(dir).filter((f) => f.endsWith(".json")).sort();
const policy = files.reduce((acc, f) => merge(acc, read(`${dir}/${f}`)), {});
const laptop = read("laptop/settings.json");

const allowList = policy.allowManagedMcpServersOnly ? policy.allowedMcpServers : [...(policy.allowedMcpServers ?? []), ...(laptop.allowedMcpServers ?? [])];
const effective = merge(laptop, policy);
effective.allowedMcpServers = allowList;

console.log(`drop-ins merged in this order: ${files.join(", ")}`);
console.log(`rhino-core@rhino enabled: ${effective.enabledPlugins["rhino-core@rhino"]}`);
console.log(`MCP servers allowed: ${effective.allowedMcpServers.map((s) => s.serverUrl).join(", ")}`);
console.log(`OTEL_LOG_USER_PROMPTS: ${effective.env.OTEL_LOG_USER_PROMPTS}`);
console.log(`denied models: ${effective.deniedModels.join(", ")}`);
EOF
